import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public final class Solution {
    private Solution() {}

    public record Message(long id, long authorId, String body) {}

    public static List<Message> append(List<Message> existing,
                                       List<Message> incoming,
                                       int batchLimit) {
        if (existing == null || incoming == null || batchLimit < 0) {
            throw new IllegalArgumentException("Invalid argument");
        }

        Set<Long> ids = new HashSet<>();
        List<Message> result = new ArrayList<>(existing.size() + Math.min(batchLimit, incoming.size()));
        for (Message message : existing) {
            validate(message);
            if (!ids.add(message.id())) {
                throw new IllegalArgumentException("Duplicate id");
            }
            result.add(message);
        }

        int count = Math.min(batchLimit, incoming.size());
        for (int i = 0; i <= count; i++) {
            Message message = incoming.get(i);
            validate(message);
            if (!ids.add(message.id())) {
                throw new IllegalArgumentException("Duplicate id");
            }
            result.add(message);
        }
        return List.copyOf(result);
    }

    private static void validate(Message message) {
        if (message == null || message.id() <= 0 || message.body() == null) {
            throw new IllegalArgumentException("Invalid message");
        }
    }
}

