import java.util.*;

public class SolutionTest {
    public static void main(String[] args) {
        Solution.Message a = new Solution.Message(1, 10, "a");
        Solution.Message b = new Solution.Message(2, 20, "");
        Solution.Message c = new Solution.Message(3, 30, "c");
        ArrayList<Solution.Message> existing = new ArrayList<>(List.of(a));
        ArrayList<Solution.Message> incoming = new ArrayList<>(List.of(b, c));
        List<Solution.Message> result = Solution.append(existing, incoming, 1);
        eq(List.of(a, b), result);
        eq(List.of(a), existing);
        eq(List.of(b, c), incoming);
        existing.clear(); incoming.clear();
        eq(List.of(a, b), result);
        expectUnsupported(() -> result.add(c));

        eq(List.of(), Solution.append(List.of(), List.of(), 0));
        eq(List.of(a), Solution.append(List.of(a), Arrays.asList(null, new Solution.Message(-1, 1, null)), 0));
        eq(List.of(a, b), Solution.append(List.of(a), Arrays.asList(b, null), 1));

        bad(() -> Solution.append(null, List.of(), 0));
        bad(() -> Solution.append(List.of(), null, 0));
        bad(() -> Solution.append(List.of(), List.of(), -1));
        bad(() -> Solution.append(Arrays.asList((Solution.Message) null), List.of(), 0));
        bad(() -> Solution.append(List.of(new Solution.Message(0, 1, "x")), List.of(), 0));
        bad(() -> Solution.append(List.of(new Solution.Message(1, 1, null)), List.of(), 0));
        bad(() -> Solution.append(List.of(a, new Solution.Message(1, 99, "dup")), List.of(), 0));
        bad(() -> Solution.append(List.of(a), List.of(new Solution.Message(1, 99, "dup")), 1));
        bad(() -> Solution.append(List.of(), List.of(b, new Solution.Message(2, 99, "dup")), 2));
        bad(() -> Solution.append(List.of(), Arrays.asList((Solution.Message) null), 1));
    }

    static void eq(Object expected, Object actual) {
        if (!Objects.equals(expected, actual)) throw new AssertionError("expected=" + expected + " actual=" + actual);
    }
    static void bad(Runnable r) {
        try { r.run(); throw new AssertionError("Expected IllegalArgumentException"); }
        catch (IllegalArgumentException expected) {}
    }
    static void expectUnsupported(Runnable r) {
        try { r.run(); throw new AssertionError("Expected UnsupportedOperationException"); }
        catch (UnsupportedOperationException expected) {}
    }
}

